import{_ as d,o as e,c as a,a2 as o}from"./chunks/framework.BM5YPQmL.js";const p=JSON.parse('{"title":"功能字典 — Open Cube OS 3.0.0 的全部命令","description":"","frontmatter":{},"headers":[],"relativePath":"zh/manual/function-dictionary.md","filePath":"zh/manual/function-dictionary.md"}'),r={name:"zh/manual/function-dictionary.md"};function c(l,t,s,h,m,i){return e(),a("div",null,[...t[0]||(t[0]=[o(`<h1 id="功能字典-—-open-cube-os-3-0-0-的全部命令" tabindex="-1">功能字典 — Open Cube OS 3.0.0 的全部命令 <a class="header-anchor" href="#功能字典-—-open-cube-os-3-0-0-的全部命令" aria-label="Permalink to &quot;功能字典 — Open Cube OS 3.0.0 的全部命令&quot;">​</a></h1><p>本页是 3.0.0 用户面的完整、无遗漏索引： <strong>311 条命令 = 300 个已注册程序 + 11 个 ush 内建命令</strong>。 下列每个程序都可以在 <code>ush&gt;</code> 提示符下按拼写原样输入 （它位于内核注册表 <code>OC_USERPROGS[]</code> 中，由 <code>tools/gen_userprogs.py</code> 从 <code>ocos/l1apps/</code> 生成）。</p><p>每条命令的详细说明位于 <a href="./commands/">commands/</a>（293 个页面， 每命令一页）。本字典补充了那些页面没有在每条目旁逐一写明的 内容：<strong>隐藏语法</strong> —— 能够工作但注册表提示或 <code>help</code> 中没有展示的 flag、子命令与参数形式。</p><h2 id="目录" tabindex="-1">目录 <a class="header-anchor" href="#目录" aria-label="Permalink to &quot;目录&quot;">​</a></h2><ul><li><a href="#如何阅读本页">如何阅读本页</a></li><li><a href="#用户面从何而来">用户面从何而来</a></li><li><a href="#mega-8--合并后的向导应用">mega (8)</a> — 各向导与 <code>direct</code> 门</li><li><a href="#l1-35--shell-本身--ring-3-扩展家族">l1 (35)</a></li><li><a href="#core-25--内核核心诊断">core (25)</a></li><li><a href="#block-24--块服务--存储">block (24)</a></li><li><a href="#display-22--显示--cjk--tui--ime">display (22)</a></li><li><a href="#nic-20--nic-服务--以太网驱动">nic (20)</a></li><li><a href="#fs-20--文件服务命令">fs (20)</a></li><li><a href="#input-18--acpi--总线--芯片组">input (18)</a></li><li><a href="#snd-17--声音服务--音频驱动">snd (17)</a></li><li><a href="#ush-16--shell-工具带文本进程文件信息">ush (16)</a></li><li><a href="#ota-16--更新--a-b--配置">ota (16)</a></li><li><a href="#net-16--网络服务">net (16)</a></li><li><a href="#camera-10--摄像头--遗留端口历史标签名">camera (10)</a></li><li><a href="#usb-9--usb-服务">usb (9)</a></li><li><a href="#power-8--电源服务">power (8)</a></li><li><a href="#crypto-4--加密--ssh">crypto (4)</a></li><li><a href="#recovery-7--杂项历史命令">recovery (7)</a></li><li><a href="#watchdog-5--klog--watchdog--health">watchdog (5)</a></li><li><a href="#time-4--时钟源">time (4)</a></li><li><a href="#12-个-ush-内建命令">12 个 ush 内建命令</a></li><li><a href="#参数如何到达其语法">参数如何到达其语法</a></li><li><a href="#命令名怪癖">命令名怪癖</a></li><li><a href="#隐藏参数总清单">隐藏参数总清单</a></li><li><a href="#help-不会强调的内容">help 不会强调的内容</a></li></ul><h2 id="如何阅读本页" tabindex="-1">如何阅读本页 <a class="header-anchor" href="#如何阅读本页" aria-label="Permalink to &quot;如何阅读本页&quot;">​</a></h2><table tabindex="0"><thead><tr><th>标记</th><th>含义</th></tr></thead><tbody><tr><td><code>⚑</code></td><td><strong>隐藏参数面</strong>：该语法可用，但注册表提示、<code>help</code> 或应用自身的 usage 行没有提到它（或仅在某个子命令的 <code>usage:</code> 中提及）。</td></tr><tr><td><em>（无）</em></td><td>该命令不接受参数（或其参数已被完整公示）。</td></tr><tr><td><em>destructive</em></td><td>会破坏数据；向导用&quot;重新输入设备名 + 裸 <code>y</code> 确认&quot;加以防护，classic/direct 分发则立即执行。</td></tr></tbody></table><p>12 个 ush 内建命令在此概述，完整文档见 <a href="./ush-reference.html">ush-reference.md</a>。测试/诊断桩（300 个中约 93 个） 有各自的深入页面：<a href="./hidden-commands.html">hidden-commands.md</a>。</p><h2 id="用户面从何而来" tabindex="-1">用户面从何而来 <a class="header-anchor" href="#用户面从何而来" aria-label="Permalink to &quot;用户面从何而来&quot;">​</a></h2><ul><li>276 条历史命令已被回归门冻结 （<code>tools/run_fix4_regression.py</code> 测得注册表 ≥ 276；3.0.0 发布 300 条）。任何命令都不能被悄悄移除。</li><li>8 个 <strong>mega 应用</strong> 在 3.0.0 中合并而成（<code>update</code>、<code>disk-tool</code>、 <code>net-tool</code>、<code>sound-tool</code>、<code>files</code>、<code>sysdiag</code>、<code>hwinfo</code>、<code>power</code>）； 历史的单命令应用仍保持注册，因此每个 op 至少有两种拼写 （见 <a href="./mega-apps.html">mega-apps.md</a>）。</li><li><code>ush</code> 和 <code>ld_so</code> 已注册但从未是 v2.2.0 的 shell 命令 （标签 <code>l1</code>）。</li></ul><h3 id="help-—-三种模式" tabindex="-1">help — 三种模式 <a class="header-anchor" href="#help-—-三种模式" aria-label="Permalink to &quot;help — 三种模式&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ush&gt; help            built-in summary + &quot;Registry: 300 programs - &#39;help -a&#39;</span></span>
<span class="line"><span>                     lists them all, &#39;help -w&#39; groups by work package.&quot;</span></span>
<span class="line"><span>ush&gt; help -a         built-ins + every registry entry, A-Z, tagged</span></span>
<span class="line"><span>ush&gt; help --all      (same)</span></span>
<span class="line"><span>ush&gt; help -w         built-ins + registry grouped by work package;</span></span>
<span class="line"><span>ush&gt; help --wp       the mega group renders FIRST</span></span></code></pre></div><p><code>help -a</code> 和 <code>help -w</code> 是多数用户从未发现的 flag；独立的 <a href="./commands/help.html">help</a> 应用接受相同的 flag。行格式为 <code> name [tag] hint</code>（hint 跟随当前 locale，zh 回退到 en）。</p><h3 id="_19-个类别标签-来自生成器的-wp-tags-已冻结" tabindex="-1">19 个类别标签（来自生成器的 WP_TAGS，已冻结） <a class="header-anchor" href="#_19-个类别标签-来自生成器的-wp-tags-已冻结" aria-label="Permalink to &quot;19 个类别标签（来自生成器的 WP_TAGS，已冻结）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>tag</th><th>n</th><th>tag</th><th>n</th><th>tag</th><th>n</th></tr></thead><tbody><tr><td>l1</td><td>35</td><td>ush</td><td>16</td><td>camera</td><td>10</td></tr><tr><td>core</td><td>25</td><td>ota</td><td>16</td><td>usb</td><td>9</td></tr><tr><td>block</td><td>24</td><td>net</td><td>16</td><td>power</td><td>8</td></tr><tr><td>display</td><td>22</td><td>input</td><td>18</td><td>mega</td><td>8</td></tr><tr><td>nic</td><td>20</td><td>snd</td><td>17</td><td>recovery</td><td>7</td></tr><tr><td>fs</td><td>20</td><td></td><td></td><td>watchdog</td><td>5</td></tr><tr><td></td><td></td><td></td><td></td><td>time</td><td>4, crypto</td></tr></tbody></table><p>类别标签是历史产物且刻意古怪：ACPI/I2C/PCI/MSI 工具归在 <code>input</code> 下，SCSI/gameport/parallel/IR 归在 <code>camera</code> 下，<code>lspci</code> 是 <code>net</code>，<code>ssh</code>/<code>sshd</code> 是 <code>crypto</code>，<code>reboot</code> 是 <code>ota</code> 而 <code>reboot_test</code> 是 <code>power</code>。不要从标签中读出语义； 它们仅是分组辅助。</p><hr><h2 id="mega-8-—-合并后的向导应用" tabindex="-1">mega (8) — 合并后的向导应用 <a class="header-anchor" href="#mega-8-—-合并后的向导应用" aria-label="Permalink to &quot;mega (8) — 合并后的向导应用&quot;">​</a></h2><p>每个 mega 应用都有<strong>三扇门</strong>：无参数 → 交互式向导； <code>&lt;app&gt; &lt;op&gt; [args]</code> → classic 分发（与历史输出逐字节一致）； <code>&lt;app&gt; direct &lt;op&gt; [args]</code> → 逐字透传。字面词 <code>direct</code> 被跳过，其余部分到达历史 op。</p><table tabindex="0"><thead><tr><th>命令</th><th>用途</th><th>隐藏 / 扩展语法</th></tr></thead><tbody><tr><td><a href="./commands/update.html">update</a></td><td>OTA 更新向导（5 步线性流程）</td><td>⚑ <code>update direct</code> = 裸在线流程；⚑ <code>update status</code> / <code>update --status</code> — A/B 槽位 + 版本状态（打印 <code>A/B disk: present</code> 锚点）；⚑ <code>update --local &lt;path&gt;</code> / <code>update local &lt;path&gt;</code> — 从包 tar.gz 离线安装</td></tr><tr><td><a href="./commands/disk-tool.html">disk-tool</a></td><td>磁盘 / 文件系统向导</td><td>⚑ <code>direct</code> 透传 30 个逐字 op 表（块 23 + 文件系统 7）：ahci, nvme, ata, dskstat, lsblk, parted, mkfs.fat32, mkfs.exfat, mkfs.ext4, fsck, sync, ahci_test, nvme_test, ata_dma_test, virtio_blk_test, disk_rw_test, partition_test, fs_mount_test, real_hw_test, abdisk, install, grub-install, abcfg, mount, mounts, umount, fatmount, fatstat, tree</td></tr><tr><td><a href="./commands/net-tool.html">net-tool</a></td><td>网络向导</td><td>⚑ <code>direct</code> 透传 16 个 op：arp, dhcp, dns, dnstest, firewall, ip, lspci, nf_test, route, tcpcc_test, tcpstats, tcptest, ssh, sshd, wifi, bt</td></tr><tr><td><a href="./commands/sound-tool.html">sound-tool</a></td><td>音频向导</td><td>⚑ <code>direct</code> 透传 17 个 op：sound, hda, ac97, sb16, es1370, virtiosnd, usbaudio, play, volume + 6 个驱动自测 + audio_rw_test, sample_rate_test</td></tr><tr><td><a href="./commands/files.html">files</a></td><td>文件管理器向导（唯一 fork/execve 的 mega 应用）</td><td>⚑ <code>direct</code> 启动真实程序：ls, tree, df, du, cp, mv, rm, edit, stat, chmod</td></tr><tr><td><a href="./commands/sysdiag.html">sysdiag</a></td><td>系统诊断向导</td><td>⚑ <code>direct</code> 透传 46 个 op 行（含双词拼写 <code>health export</code>、<code>health watch</code>）；crashtest 只能通过 classic/direct 触达 —— 刻意不设为向导按钮</td></tr><tr><td><a href="./commands/hwinfo.html">hwinfo</a></td><td>只读硬件清单向导</td><td>⚑ <code>direct</code> 透传 26 个只读 op（display/time/pci/acpi/usb/camera/input 家族）</td></tr><tr><td><a href="./commands/power.html">power</a></td><td>电源向导</td><td>⚑ <code>direct</code> 透传 9 个 op：shutdown, poweroff, reboot, halt, sleep, poweroff_test, suspend_test, halt_test, reboot_test</td></tr></tbody></table><p><code>direct</code> 关键字在所有注册表提示中均未记载 —— 只在 各应用的 <code>usage()</code> 文本中记录。<code>update</code>、<code>disk-tool lsblk</code> 和 <code>disk-tool direct lsblk</code> 是同一服务 op 的三种等价拼写。</p><h2 id="l1-35-—-shell-本身-ring-3-扩展家族" tabindex="-1">l1 (35) — shell 本身 + ring-3 扩展家族 <a class="header-anchor" href="#l1-35-—-shell-本身-ring-3-扩展家族" aria-label="Permalink to &quot;l1 (35) — shell 本身 + ring-3 扩展家族&quot;">​</a></h2><table tabindex="0"><thead><tr><th>命令</th><th>用途</th><th>隐藏 / 扩展语法</th></tr></thead><tbody><tr><td><a href="./commands/ush.html">ush</a></td><td>ring-3 shell（默认启动项）</td><td>裸 ELF，未 gzipped；见 <a href="./ush-reference.html">ush-reference.md</a></td></tr><tr><td>ld_so</td><td>动态加载器本身（映射于 0x10000000）</td><td>平坦模型 <code>ld_so.c</code> + <code>ld_so.ld</code>；不打算被输入</td></tr><tr><td><a href="./commands/ldd.html">ldd</a></td><td>动态依赖列表器</td><td>⚑ 读取任意注册表程序的 PT_INTERP + DT_NEEDED：<code>ldd &lt;program&gt;</code></td></tr><tr><td>l1test</td><td>L1 作业/IPC/动态链接自测</td><td>无参数；PASS/FAIL 判定块</td></tr><tr><td>hello</td><td>hello world（平坦 asm）</td><td>作业控制固定件</td></tr><tr><td>loop</td><td>空闲循环（平坦 asm）</td><td>作业测试目标；永久忙等（见 GitHub Issues）</td></tr><tr><td>badapp</td><td>故意行为不端的应用（平坦 asm）</td><td>崩溃路径固定件</td></tr><tr><td>dyn_hello</td><td>动态链接测试程序</td><td>打印 <code>hello from dynamic program</code></td></tr><tr><td>main_dyn</td><td>动态主镜像测试</td><td>动态链接固定件</td></tr><tr><td>pie_test</td><td>PIE 加载测试</td><td>打印其加载基址 <code>loaded at 0x...</code></td></tr><tr><td>reloc_test</td><td>重定位测试</td><td>打印 <code>foo_add=30 foo_global=42 fp=300</code></td></tr><tr><td>so_test</td><td>共享库调用测试</td><td>打印 <code>foo_add(2,3)=5</code>（libfoo.c 是内嵌 solib）</td></tr><tr><td>dlsym_test</td><td>dlsym 解析测试</td><td>打印 <code>foo_add(7,8)=15</code></td></tr><tr><td>exec_test</td><td>execve 面探针</td><td>平坦的内核面探针</td></tr><tr><td>fork_test</td><td>fork 面探针</td><td>平坦</td></tr><tr><td>fdref_test</td><td>fd 引用计数（dup/fork 继承）探针</td><td>平坦</td></tr><tr><td>pipe_test</td><td>pipe 系统调用探针</td><td>平坦</td></tr><tr><td>select_test</td><td>select 系统调用探针</td><td>平坦</td></tr><tr><td>select_zero_test</td><td>零 fd 的 select 探针</td><td>平坦</td></tr><tr><td>signal_test</td><td>信号投递探针</td><td>平坦</td></tr><tr><td>sigsegv_test</td><td>ring-3 中故意的 SIGSEGV</td><td>内核存活，进程被杀</td></tr><tr><td>sse_test</td><td>SSE 状态保存探针</td><td>平坦</td></tr><tr><td>stackovf</td><td>故意的用户栈溢出</td><td>遏制固定件</td></tr><tr><td>int3_user</td><td>ring-3 #BP 触发</td><td>遏制固定件</td></tr><tr><td>priv_test</td><td>特权指令拒绝探针</td><td>平坦</td></tr><tr><td>pf_test</td><td>ring-3 缺页探针</td><td>平坦</td></tr><tr><td>p3_test</td><td>优先级调度探针</td><td>平坦</td></tr><tr><td>mmap_test</td><td>mmap 系统调用探针</td><td>平坦</td></tr><tr><td>mmap_multi</td><td>多重映射探针</td><td>平坦</td></tr><tr><td>mprotect_test</td><td>mprotect 探针</td><td>平坦</td></tr><tr><td>g6_test</td><td>G6 进程组里程碑测试</td><td>完整链；异步汇总 <code>failed tests = 0</code></td></tr><tr><td>g6_exec_a / g6_exec_b</td><td>G6 exec 两半</td><td>由 g6_test 运行</td></tr><tr><td>g6_oom</td><td>G6 OOM 路径测试</td><td>平坦</td></tr><tr><td>g7mmap</td><td>G7 mmap 里程碑测试</td><td>平坦</td></tr></tbody></table><h2 id="core-25-—-内核核心诊断" tabindex="-1">core (25) — 内核核心诊断 <a class="header-anchor" href="#core-25-—-内核核心诊断" aria-label="Permalink to &quot;core (25) — 内核核心诊断&quot;">​</a></h2><table tabindex="0"><thead><tr><th>命令</th><th>用途</th><th>隐藏 / 扩展语法</th></tr></thead><tbody><tr><td><a href="./commands/cr3test.html">cr3test</a></td><td>CR3 寄存器审计</td><td>无参数</td></tr><tr><td><a href="./commands/crashlog.html">crashlog</a></td><td>崩溃转储记录（32 槽环形）</td><td>无参数；空 → <code>no dump captured yet (trigger: crashtest panic|exc|pf)</code></td></tr><tr><td><a href="./commands/frag.html">frag</a></td><td>PMM 碎片报告</td><td>无参数</td></tr><tr><td><a href="./commands/heap.html">heap</a></td><td>内核堆统计</td><td>无参数</td></tr><tr><td><a href="./commands/heapbounds.html">heapbounds</a></td><td>堆边界检查</td><td>无参数</td></tr><tr><td><a href="./commands/heaptest.html">heaptest</a></td><td>堆压力测试</td><td>无参数</td></tr><tr><td><a href="./commands/irqabitest.html">irqabitest</a></td><td>IRQ 亲和性测试</td><td>无参数</td></tr><tr><td><a href="./commands/kill.html">kill</a></td><td>终止一个进程</td><td><code>kill &lt;pid&gt;</code> — 恒为 SIGKILL (9)；ocire_guard 代理无法被杀</td></tr><tr><td><a href="./commands/mem.html">mem</a></td><td>物理内存统计</td><td>无参数</td></tr><tr><td><a href="./commands/memtest.html">memtest</a></td><td>内存服务测试组</td><td>无参数</td></tr><tr><td><a href="./commands/multi.html">multi</a></td><td>多核唤醒测试（3 个交错任务）</td><td>无参数</td></tr><tr><td><a href="./commands/nice.html">nice</a></td><td>优先级演示</td><td>⚑ <code>nice &lt;tid&gt; &lt;prio&gt;</code> — 是 tid 不是 pid；0 = 最高 … 31 = 最低</td></tr><tr><td>p0leak</td><td>用户指针校验围栏测试（平坦 asm）</td><td>打印 <code>all kernel-address probes fenced</code></td></tr><tr><td><a href="./commands/p2test.html">p2test</a></td><td>live-fix 探针</td><td>⚑ <code>p2test utf8</code> / <code>p2test read0</code> / <code>p2test pipe</code> — 三个不同探针（见 <a href="./hidden-commands.html">hidden-commands.md</a>）</td></tr><tr><td><a href="./commands/pftest.html">pftest</a></td><td>缺页处理测试</td><td>无参数</td></tr><tr><td><a href="./commands/pmmrace.html">pmmrace</a></td><td>PMM 竞态检测器</td><td>无参数</td></tr><tr><td><a href="./commands/ps.html">ps</a></td><td>列出进程</td><td>无参数</td></tr><tr><td><a href="./commands/run.html">run</a></td><td>带参数运行一个程序</td><td><code>run &lt;name&gt; [args...]</code> — 对任意注册表名 fork+execve</td></tr><tr><td><a href="./commands/sched.html">sched</a></td><td>调度器统计</td><td>无参数</td></tr><tr><td><a href="./commands/spawn.html">spawn</a></td><td>后台孵化演示</td><td>无参数</td></tr><tr><td><a href="./commands/syncstat.html">syncstat</a></td><td>同步原语统计</td><td>无参数</td></tr><tr><td><a href="./commands/synctest.html">synctest</a></td><td>同步原语测试</td><td>无参数</td></tr><tr><td><a href="./commands/vmkernelpt.html">vmkernelpt</a></td><td>内核页表转储</td><td>无参数</td></tr><tr><td><a href="./commands/vmmap.html">vmmap</a></td><td>地址空间映射转储</td><td>无参数</td></tr><tr><td><a href="./commands/vmtest.html">vmtest</a></td><td>VMM 单元测试</td><td>无参数</td></tr></tbody></table><h2 id="block-24-—-块服务-存储" tabindex="-1">block (24) — 块服务 + 存储 <a class="header-anchor" href="#block-24-—-块服务-存储" aria-label="Permalink to &quot;block (24) — 块服务 + 存储&quot;">​</a></h2><table tabindex="0"><thead><tr><th>命令</th><th>用途</th><th>隐藏 / 扩展语法</th></tr></thead><tbody><tr><td><a href="./commands/abcfg.html">abcfg</a></td><td>A/B 槽位配置</td><td>无参数</td></tr><tr><td><a href="./commands/abdisk.html">abdisk</a></td><td>A/B 槽位磁盘工具 <em>（destructive，重新分区）</em></td><td><code>abdisk &lt;device&gt;</code> — 向导中有防护，classic 形式立即执行</td></tr><tr><td><a href="./commands/ahci.html">ahci</a></td><td>AHCI 控制器状态</td><td>无参数</td></tr><tr><td><a href="./commands/ahci_test.html">ahci_test</a></td><td>AHCI 端口测试</td><td>无参数</td></tr><tr><td><a href="./commands/ata.html">ata</a></td><td>ATA/IDE 状态</td><td>无参数</td></tr><tr><td><a href="./commands/ata_dma_test.html">ata_dma_test</a></td><td>ATA DMA 测试</td><td>无参数</td></tr><tr><td><a href="./commands/disk_rw_test.html">disk_rw_test</a></td><td>磁盘读写测试</td><td><code>disk_rw_test &lt;device&gt;</code></td></tr><tr><td><a href="./commands/dskstat.html">dskstat</a></td><td>磁盘 I/O 统计</td><td>无参数</td></tr><tr><td><a href="./commands/fs_mount_test.html">fs_mount_test</a></td><td>文件系统挂载测试</td><td><code>fs_mount_test &lt;device&gt;</code> — <strong>会格式化该设备</strong></td></tr><tr><td><a href="./commands/fsck.html">fsck</a></td><td>检查文件系统（仅 FAT32）</td><td><code>fsck &lt;device&gt;</code></td></tr><tr><td><a href="./commands/grub-install.html">grub-install</a></td><td>安装 OCBL 引导链</td><td><code>grub-install &lt;device&gt;</code></td></tr><tr><td><a href="./commands/install.html">install</a></td><td>将 Open Cube OS 安装到磁盘 <em>（destructive）</em></td><td><code>install &lt;device&gt;</code>（需要 ≥ 64 MiB）</td></tr><tr><td><a href="./commands/lsblk.html">lsblk</a></td><td>列出块设备</td><td>无参数</td></tr><tr><td><a href="./commands/mkfs-fat32.html">mkfs.fat32</a></td><td>创建 FAT32 文件系统 <em>（destructive）</em></td><td><code>mkfs.fat32 &lt;device&gt;</code></td></tr><tr><td><a href="./commands/mkfs-exfat.html">mkfs.exfat</a></td><td>创建 exFAT 文件系统 <em>（destructive）</em></td><td><code>mkfs.exfat &lt;device&gt;</code>（需要 ≥ 65 扇区 + FAT + 堆）</td></tr><tr><td><a href="./commands/mkfs-ext4.html">mkfs.ext4</a></td><td>创建 ext4 文件系统 <em>（destructive）</em></td><td><code>mkfs.ext4 &lt;device&gt;</code></td></tr><tr><td><a href="./commands/nvme.html">nvme</a></td><td>NVMe 控制器状态</td><td>无参数</td></tr><tr><td><a href="./commands/nvme_test.html">nvme_test</a></td><td>NVMe 命名空间测试</td><td>无参数</td></tr><tr><td><a href="./commands/parted.html">parted</a></td><td>分区表编辑器（查看）</td><td>⚑ <code>parted [device]</code> — 可选的设备参数容易被忽略</td></tr><tr><td><a href="./commands/partition_test.html">partition_test</a></td><td>分区扫描测试</td><td><code>partition_test &lt;device&gt;</code></td></tr><tr><td><a href="./commands/real_hw_test.html">real_hw_test</a></td><td>真实硬件磁盘测试</td><td>无参数（含一节 NIC 内容）</td></tr><tr><td><a href="./commands/sync.html">sync</a></td><td>将块缓存刷写到磁盘</td><td>无参数（64 槽 LRU 写回缓存 + 每设备 FLUSH）</td></tr><tr><td><a href="./commands/virtio_blk_test.html">virtio_blk_test</a></td><td>virtio-blk 测试</td><td>无参数</td></tr><tr><td><a href="./commands/write.html">write</a></td><td>将 stdin 写入文件</td><td><code>write &lt;file&gt;</code>，here-tagin；EOF 结束</td></tr></tbody></table><h2 id="display-22-—-显示-cjk-tui-ime" tabindex="-1">display (22) — 显示 / CJK / TUI / IME <a class="header-anchor" href="#display-22-—-显示-cjk-tui-ime" aria-label="Permalink to &quot;display (22) — 显示 / CJK / TUI / IME&quot;">​</a></h2><table tabindex="0"><thead><tr><th>命令</th><th>用途</th><th>隐藏 / 扩展语法</th></tr></thead><tbody><tr><td><a href="./commands/chinese.html">chinese</a></td><td>CJK 控制台演示</td><td>无参数</td></tr><tr><td><a href="./commands/chinesetest.html">chinesetest</a></td><td>CJK 字体/编码测试组</td><td>无参数</td></tr><tr><td><a href="./commands/clear.html">clear</a></td><td>清屏</td><td>无参数</td></tr><tr><td><a href="./commands/encoding.html">encoding</a></td><td>控制台编码状态/设置</td><td>无参数</td></tr><tr><td>encoding-test</td><td>编码编解码器测试</td><td>无参数</td></tr><tr><td><a href="./commands/font.html">font</a></td><td>字体引擎状态</td><td>无参数</td></tr><tr><td>font-test</td><td>字体渲染器测试</td><td>无参数</td></tr><tr><td><a href="./commands/ime.html">ime</a></td><td>拼音 IME 状态</td><td>⚑ <code>ime -i</code> — 交互式组词行（可选开启，以保证脚本化串口会话保持纯净）；数字 1-9 选择，空格 = 第一个，PgUp/PgDn 或 <code>-</code>/<code>=</code> 翻页，Backspace 退一字，Enter 提交原始串，Esc 取消</td></tr><tr><td>ime-test</td><td>IME 引擎 + 会话测试组</td><td>无参数（含词组/翻页/数字选择的协议断言）</td></tr><tr><td><a href="./commands/lang.html">lang</a></td><td>显示/设置控制台语言</td><td><code>lang [en|zh]</code> — 每个由 tr_() 驱动的界面实时切换</td></tr><tr><td><a href="./commands/serial_encoding.html">serial_encoding</a></td><td>串口线路编码</td><td>⚑ <code>serial_encoding [utf8|gbk]</code></td></tr><tr><td><a href="./commands/stats.html">stats</a></td><td>显示管线统计</td><td>无参数</td></tr><tr><td><a href="./commands/tui.html">tui</a></td><td>TUI 桌面</td><td>全屏；热键见 <a href="./ush-reference.html">ush-reference.md</a> §TUI</td></tr><tr><td>tui-drv</td><td>TUI 驱动页</td><td>全屏页面</td></tr><tr><td>tui-ext</td><td>TUI 扩展页</td><td>全屏页面</td></tr><tr><td>tui-hw</td><td>TUI 硬件页集</td><td>全屏页面（system/CPU、PCI、sound、storage、network）</td></tr><tr><td>tui-net</td><td>TUI 网络页</td><td>全屏页面</td></tr><tr><td>tui-sys</td><td>TUI 系统页</td><td>全屏页面</td></tr><tr><td>tui-sysinfo</td><td>TUI sysinfo 页 + 共享帮助屏</td><td>全屏页面</td></tr><tr><td>tui-time</td><td>TUI 时钟页</td><td>全屏页面</td></tr><tr><td>tui-test</td><td>TUI 自测组</td><td>经捕获路径的判定块</td></tr><tr><td><a href="./commands/uname.html">uname</a></td><td>系统标识</td><td>⚑ <code>uname -a</code> — hwinfo 向导弹调用的正是它</td></tr></tbody></table><h2 id="nic-20-—-nic-服务-以太网驱动" tabindex="-1">nic (20) — NIC 服务 + 以太网驱动 <a class="header-anchor" href="#nic-20-—-nic-服务-以太网驱动" aria-label="Permalink to &quot;nic (20) — NIC 服务 + 以太网驱动&quot;">​</a></h2><table tabindex="0"><thead><tr><th>命令</th><th>用途</th><th>隐藏 / 扩展语法</th></tr></thead><tbody><tr><td><a href="./commands/bcm57xx.html">bcm57xx</a></td><td>Broadcom NIC 状态</td><td>无参数</td></tr><tr><td><a href="./commands/e1000e.html">e1000e</a></td><td>Intel e1000e NIC 状态</td><td>无参数</td></tr><tr><td><a href="./commands/igb.html">igb</a></td><td>Intel igb NIC 状态</td><td>无参数</td></tr><tr><td><a href="./commands/ixgbe.html">ixgbe</a></td><td>Intel ixgbe NIC 状态</td><td>无参数</td></tr><tr><td><a href="./commands/rtl810x.html">rtl810x</a></td><td>Realtek rtl810x NIC 状态</td><td>无参数</td></tr><tr><td><a href="./commands/rtl8125.html">rtl8125</a></td><td>Realtek rtl8125 NIC 状态</td><td>无参数</td></tr><tr><td><a href="./commands/rtl8139.html">rtl8139</a></td><td>Realtek rtl8139 NIC 状态</td><td>无参数</td></tr><tr><td><a href="./commands/rtl8168.html">rtl8168</a></td><td>Realtek rtl8168 NIC 状态</td><td>无参数</td></tr><tr><td>bcm57xx_test … rtl8168_test (8)</td><td>每驱动自测</td><td>无参数</td></tr><tr><td><a href="./commands/bt.html">bt</a></td><td>蓝牙状态</td><td>⚑ 子词：<code>bt usb</code>（HCI-USB 传输）、<code>bt uart</code>（H4 UART）、<code>bt test</code>（流程自测）</td></tr><tr><td><a href="./commands/nic_rw_test.html">nic_rw_test</a></td><td>NIC 环回测试</td><td>无参数</td></tr><tr><td><a href="./commands/other_nic_test.html">other_nic_test</a></td><td>其他 NIC 驱动测试（3c59x/nForce/Atheros/Marvell）</td><td>无参数</td></tr><tr><td><a href="./commands/wifi.html">wifi</a></td><td>无线状态/扫描</td><td>⚑ <code>wifi scan</code>（被动信标扫描；QEMU 中如实报告 <code>no radio</code>）、<code>wifi test</code>（核心 + 每家族自测）、<code>wifi sdio</code>（SDHCI 总线状态 + 自测）</td></tr></tbody></table><h2 id="fs-20-—-文件服务命令" tabindex="-1">fs (20) — 文件服务命令 <a class="header-anchor" href="#fs-20-—-文件服务命令" aria-label="Permalink to &quot;fs (20) — 文件服务命令&quot;">​</a></h2><table tabindex="0"><thead><tr><th>命令</th><th>用途</th><th>隐藏 / 扩展语法</th></tr></thead><tbody><tr><td><a href="./commands/cat.html">cat</a></td><td>打印文件内容</td><td>无 flag</td></tr><tr><td><a href="./commands/cp.html">cp</a></td><td>复制文件</td><td><code>cp &lt;src&gt; &lt;dst&gt;</code>（无同文件防护——见 GitHub Issues）</td></tr><tr><td><a href="./commands/df.html">df</a></td><td>文件系统剩余空间</td><td>无参数</td></tr><tr><td><a href="./commands/du.html">du</a></td><td>文件空间占用</td><td><code>du [path]</code></td></tr><tr><td><a href="./commands/edit.html">edit</a></td><td>经典行编辑器界面</td><td>与 nano 完全相同（第二种拼写）；F2 = IME</td></tr><tr><td><a href="./commands/fatmount.html">fatmount</a></td><td>挂载 FAT32 卷</td><td><code>fatmount [dev] [path]</code>；不会预先创建挂载点</td></tr><tr><td><a href="./commands/fatstat.html">fatstat</a></td><td>FAT32 卷统计</td><td><code>fatstat [dev]</code> — 显示解析出的 BPB</td></tr><tr><td><a href="./commands/fstest.html">fstest</a></td><td>VFS 压力测试</td><td>无参数</td></tr><tr><td><a href="./commands/grep.html">grep</a></td><td>搜索文本</td><td>stdin 过滤器，仅单一模式 — 无文件参数，无正则 flag</td></tr><tr><td><a href="./commands/ls.html">ls</a></td><td>列出目录</td><td><code>ls [path]</code>；条目标注 <code>d</code>/<code>c</code>/<code>-</code>；<strong>不做通配符展开</strong></td></tr><tr><td><a href="./commands/mkdir.html">mkdir</a></td><td>创建目录</td><td><code>mkdir &lt;path&gt;</code></td></tr><tr><td><a href="./commands/mount.html">mount</a></td><td>挂载 / 列出挂载</td><td>⚑ <code>mount</code> 列出；<code>mount &lt;type&gt; &lt;device&gt; &lt;path&gt;</code> 挂载（会预先创建挂载点）</td></tr><tr><td><a href="./commands/mounts.html">mounts</a></td><td>列出已挂载文件系统</td><td>无参数</td></tr><tr><td><a href="./commands/mv.html">mv</a></td><td>移动/重命名</td><td><code>mv &lt;src&gt; &lt;dst&gt;</code></td></tr><tr><td><a href="./commands/pwd.html">pwd</a></td><td>工作目录</td><td>无参数</td></tr><tr><td><a href="./commands/rm.html">rm</a></td><td>删除文件</td><td><code>rm &lt;path&gt;</code></td></tr><tr><td><a href="./commands/rmdir.html">rmdir</a></td><td>删除空目录</td><td><code>rmdir &lt;path&gt;</code></td></tr><tr><td><a href="./commands/touch.html">touch</a></td><td>创建空文件 / 更新 mtime</td><td><code>touch &lt;path&gt;</code></td></tr><tr><td><a href="./commands/tree.html">tree</a></td><td>目录树</td><td><code>tree [path]</code>；深度上限 16，深度 ≥ 12 处显示 <code>…</code></td></tr><tr><td><a href="./commands/umount.html">umount</a></td><td>卸载</td><td><code>umount &lt;path&gt;</code></td></tr></tbody></table><h2 id="input-18-—-acpi-总线-芯片组" tabindex="-1">input (18) — ACPI + 总线 + 芯片组 <a class="header-anchor" href="#input-18-—-acpi-总线-芯片组" aria-label="Permalink to &quot;input (18) — ACPI + 总线 + 芯片组&quot;">​</a></h2><table tabindex="0"><thead><tr><th>命令</th><th>用途</th><th>隐藏 / 扩展语法</th></tr></thead><tbody><tr><td><a href="./commands/acpi.html">acpi</a></td><td>ACPI 表摘要</td><td>无参数</td></tr><tr><td><a href="./commands/acpidev.html">acpidev</a></td><td>ACPI 设备树</td><td>无参数</td></tr><tr><td><a href="./commands/acpipow.html">acpipow</a></td><td>ACPI 电源状态</td><td>无参数</td></tr><tr><td><a href="./commands/acpitest.html">acpitest</a></td><td>ACPI 解析器测试</td><td>无参数</td></tr><tr><td><a href="./commands/exc.html">exc</a></td><td>异常报告状态</td><td>无参数</td></tr><tr><td><a href="./commands/i2cdetect.html">i2cdetect</a></td><td>扫描 I2C 总线</td><td>无参数</td></tr><tr><td><a href="./commands/i2cget.html">i2cget</a></td><td>读取 I2C 寄存器</td><td>⚑ <code>i2cget &lt;bus&gt; &lt;addr&gt; [reg]</code> — 全为十六进制</td></tr><tr><td><a href="./commands/i2cset.html">i2cset</a></td><td>写入 I2C 寄存器</td><td>⚑ <code>i2cset &lt;bus&gt; &lt;addr&gt; &lt;reg&gt; &lt;val&gt;</code> — 十六进制</td></tr><tr><td><a href="./commands/i2ctest.html">i2ctest</a></td><td>I2C 总线测试</td><td>无参数</td></tr><tr><td><a href="./commands/msitest.html">msitest</a></td><td>MSI 中断测试</td><td>无参数；在一块 e1000 上执行<strong>真实 MSI 触发</strong>（见 <a href="./hidden-commands.html">hidden-commands.md</a>）</td></tr><tr><td><a href="./commands/pcibars.html">pcibars</a></td><td>PCI BAR 分配检查</td><td>无参数</td></tr><tr><td><a href="./commands/pcidump.html">pcidump</a></td><td>转储 PCI 配置</td><td>⚑ <code>pcidump &lt;bus:dev.fn&gt;</code> 例如 <code>pcidump 0:1f.3</code>；无参数 = 摘要</td></tr><tr><td><a href="./commands/pcie.html">pcie</a></td><td>PCIe 链路状态</td><td>无参数</td></tr><tr><td><a href="./commands/smbus.html">smbus</a></td><td>SMBus 状态</td><td>无参数</td></tr><tr><td><a href="./commands/smbustest.html">smbustest</a></td><td>SMBus 测试</td><td>无参数</td></tr><tr><td><a href="./commands/timer.html">timer</a></td><td>定时器测试</td><td>无参数</td></tr><tr><td><a href="./commands/touchpad.html">touchpad</a></td><td>触摸板状态</td><td>无参数</td></tr><tr><td><a href="./commands/touchtest.html">touchtest</a></td><td>触摸板测试</td><td>无参数</td></tr></tbody></table><h2 id="snd-17-—-声音服务-音频驱动" tabindex="-1">snd (17) — 声音服务 + 音频驱动 <a class="header-anchor" href="#snd-17-—-声音服务-音频驱动" aria-label="Permalink to &quot;snd (17) — 声音服务 + 音频驱动&quot;">​</a></h2><table tabindex="0"><thead><tr><th>命令</th><th>用途</th><th>隐藏 / 扩展语法</th></tr></thead><tbody><tr><td><a href="./commands/sound.html">sound</a></td><td>音频子系统状态（设备列表）</td><td>无参数</td></tr><tr><td><a href="./commands/hda.html">hda</a></td><td>Intel HD Audio 状态</td><td>无参数</td></tr><tr><td><a href="./commands/ac97.html">ac97</a></td><td>AC&#39;97 状态</td><td>无参数</td></tr><tr><td><a href="./commands/sb16.html">sb16</a></td><td>SoundBlaster 16 状态</td><td>无参数</td></tr><tr><td><a href="./commands/es1370.html">es1370</a></td><td>Ensoniq ES1370 状态</td><td>无参数</td></tr><tr><td><a href="./commands/virtiosnd.html">virtiosnd</a></td><td>virtio-snd 状态</td><td>无参数</td></tr><tr><td><a href="./commands/usbaudio.html">usbaudio</a></td><td>USB 音频状态</td><td>无参数</td></tr><tr><td>hda_test / ac97_test / sb16_test / es1370_test / virtio_snd_test / usb_audio_test (6)</td><td>每驱动播放自测</td><td>无参数</td></tr><tr><td><a href="./commands/audio_rw_test.html">audio_rw_test</a></td><td>PCM 读写环回测试</td><td>无参数</td></tr><tr><td><a href="./commands/sample_rate_test.html">sample_rate_test</a></td><td>采样率精度测试</td><td>无参数（如实给出 QEMU 44.1 kHz 的限制说明）</td></tr><tr><td><a href="./commands/play.html">play</a></td><td>播放 WAV 文件 / 测试音</td><td>⚑ <code>play [device] [rate]</code> — rate 4000..96000；裸调用 = 440 Hz 音</td></tr><tr><td><a href="./commands/volume.html">volume</a></td><td>混音器音量控制</td><td>⚑ <code>volume [device] [0-100]</code> — 服务端做钳制</td></tr></tbody></table><h2 id="ush-16-—-shell-工具带-文本-进程-文件信息" tabindex="-1">ush (16) — shell 工具带（文本/进程/文件信息） <a class="header-anchor" href="#ush-16-—-shell-工具带-文本-进程-文件信息" aria-label="Permalink to &quot;ush (16) — shell 工具带（文本/进程/文件信息）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>命令</th><th>用途</th><th>隐藏 / 扩展语法</th></tr></thead><tbody><tr><td><a href="./commands/awk.html">awk</a></td><td>模式扫描</td><td>仅支持 <code>{print ...}</code> 脚本；否则 <code>awk: missing {print ...}</code></td></tr><tr><td><a href="./commands/chmod.html">chmod</a></td><td>更改文件权限</td><td><code>chmod &lt;mode&gt; &lt;path&gt;</code>（八进制）</td></tr><tr><td><a href="./commands/chown.html">chown</a></td><td>更改文件属主</td><td><code>chown &lt;owner&gt; &lt;path&gt;</code></td></tr><tr><td><a href="./commands/date.html">date</a></td><td>来自 RTC 的日期/时间</td><td>无参数；回退时打印 <code>ms since boot (no RTC driver)</code></td></tr><tr><td><a href="./commands/free.html">free</a></td><td>内存使用摘要</td><td>无参数</td></tr><tr><td><a href="./commands/head.html">head</a></td><td>文件的前几行</td><td><code>head &lt;file&gt;</code></td></tr><tr><td><a href="./commands/ln.html">ln</a></td><td>创建链接</td><td>⚑ <code>ln -s &lt;abs-target&gt; &lt;linkpath&gt;</code> — 符号链接（目标必须为绝对路径）；默认 = 硬链接</td></tr><tr><td><a href="./commands/nano.html">nano</a></td><td>nano 风格编辑器</td><td>F2 切换中文 IME；完整按键表见 <a href="./ush-reference.html">ush-reference.md</a></td></tr><tr><td><a href="./commands/sed.html">sed</a></td><td>流编辑器</td><td>⚑ <code>sed s/old/new/[g]</code>、<code>sed -n Np</code>、<code>sed Nd</code> — 替换 / 打印第 N 行 / 删除第 N 行，作用于 stdin 或可选的尾随文件</td></tr><tr><td><a href="./commands/sort.html">sort</a></td><td>行排序</td><td>stdin → stdout</td></tr><tr><td><a href="./commands/stat.html">stat</a></td><td>文件元数据</td><td><code>stat &lt;path&gt;</code></td></tr><tr><td><a href="./commands/tail.html">tail</a></td><td>文件的最后几行</td><td><code>tail &lt;file&gt;</code></td></tr><tr><td><a href="./commands/top.html">top</a></td><td>实时进程总览</td><td>⚑ <code>top -n N</code> — 刷新 N 次（钳制 1..10），间隔 1 s；<strong>不在 usage 文本中</strong></td></tr><tr><td><a href="./commands/uniq.html">uniq</a></td><td>去除相邻重复行</td><td>stdin → stdout</td></tr><tr><td><a href="./commands/vi.html">vi</a></td><td>模式化 vi 编辑器</td><td>i/a/o 插入，dd/yy/p，<code>:w</code>/<code>:q</code>/<code>:wq</code>/<code>:q!</code>；F2 = IME</td></tr><tr><td><a href="./commands/wc.html">wc</a></td><td>统计行/词/字节</td><td><code>wc &lt;file&gt;</code></td></tr></tbody></table><h2 id="ota-16-—-更新-a-b-配置" tabindex="-1">ota (16) — 更新 / A-B / 配置 <a class="header-anchor" href="#ota-16-—-更新-a-b-配置" aria-label="Permalink to &quot;ota (16) — 更新 / A-B / 配置&quot;">​</a></h2><table tabindex="0"><thead><tr><th>命令</th><th>用途</th><th>隐藏 / 扩展语法</th></tr></thead><tbody><tr><td><a href="./commands/ab_partition_test.html">ab_partition_test</a></td><td>A/B 分区测试</td><td>无参数</td></tr><tr><td><a href="./commands/checkupdate.html">checkupdate</a></td><td>检查 OTA 更新</td><td>无参数；<code>Current version is up to date.</code> 或 <code>New version available.</code></td></tr><tr><td><a href="./commands/checkupdate_test.html">checkupdate_test</a></td><td>OTA 检查测试</td><td>无参数</td></tr><tr><td><a href="./commands/config.html">config</a></td><td>系统配置存储</td><td>⚑ <code>config list</code> | <code>config get &lt;key&gt;</code> | <code>config set &lt;key&gt; &lt;value&gt;</code> | <code>config restore</code> | <code>config path</code></td></tr><tr><td><a href="./commands/config_test.html">config_test</a></td><td>配置后端测试</td><td>无参数</td></tr><tr><td><a href="./commands/real_update_test.html">real_update_test</a></td><td>完整真实 OTA 流程测试</td><td>无参数</td></tr><tr><td><a href="./commands/reboot.html">reboot</a></td><td>重启机器</td><td>无参数（标签为 <code>ota</code>，不是 <code>power</code>）</td></tr><tr><td><a href="./commands/rollback.html">rollback</a></td><td>回滚到另一个 A/B 槽位</td><td>无参数</td></tr><tr><td>update_check_test / update_download_test / update_install_test / update_local_test / update_pkg_test / update_rollback_test / update_status_test / update_verify_test (8)</td><td>更新单元测试家族</td><td>无参数</td></tr></tbody></table><h2 id="net-16-—-网络服务" tabindex="-1">net (16) — 网络服务 <a class="header-anchor" href="#net-16-—-网络服务" aria-label="Permalink to &quot;net (16) — 网络服务&quot;">​</a></h2><table tabindex="0"><thead><tr><th>命令</th><th>用途</th><th>隐藏 / 扩展语法</th></tr></thead><tbody><tr><td><a href="./commands/arp.html">arp</a></td><td>ARP 表（只读，16 条目）</td><td>无参数</td></tr><tr><td><a href="./commands/dhcp.html">dhcp</a></td><td>获取 DHCP 租约</td><td>无参数；打印 <code>DHCP success: IP=...</code> 锚点；超时非零退出</td></tr><tr><td><a href="./commands/dns.html">dns</a></td><td>解析主机名</td><td>⚑ <code>dns &lt;name&gt; [aaaa|cname|mx|txt|ns|srv]</code> — 记录类型选择器可选</td></tr><tr><td><a href="./commands/dnstest.html">dnstest</a></td><td>DNS 解析器测试组</td><td>无参数（内建向量含 10.0.2.2/update.json 固定件）</td></tr><tr><td><a href="./commands/firewall.html">firewall</a></td><td>包过滤规则</td><td>⚑ <code>firewall</code>（列表） | <code>firewall add [in|out|fwd] &lt;drop|accept|reject&gt; &lt;tcp|udp|icmp|any&gt; [port &lt;n&gt;] [src &lt;ip&gt;] [dst &lt;ip&gt;] [state &lt;new|est|any&gt;]</code> | <code>firewall del &lt;n&gt;</code> | <code>firewall policy &lt;in|out|fwd&gt; &lt;accept|drop&gt;</code> | <code>firewall ct</code>（conntrack） | <code>firewall reset</code></td></tr><tr><td><a href="./commands/ifconfig.html">ifconfig</a></td><td>接口状态（只读）</td><td>无参数</td></tr><tr><td><a href="./commands/ip.html">ip</a></td><td>IP 配置</td><td>⚑ <code>ip</code> 显示；<code>ip &lt;ip&gt; &lt;mask&gt; &lt;gw&gt;</code> 设置</td></tr><tr><td><a href="./commands/lspci.html">lspci</a></td><td>列出 PCI 设备（标签 <code>net</code>）</td><td>无参数</td></tr><tr><td><a href="./commands/netstat.html">netstat</a></td><td>套接字/连接统计</td><td>无参数</td></tr><tr><td><a href="./commands/nf_test.html">nf_test</a></td><td>netfilter 测试</td><td>无参数</td></tr><tr><td><a href="./commands/ping.html">ping</a></td><td>ICMP 回显</td><td><code>ping &lt;host|ip&gt;</code>；先做 DNS 解析；4 次探测 @ 3000 ms</td></tr><tr><td><a href="./commands/route.html">route</a></td><td>路由表</td><td>⚑ <code>route</code> 显示；<code>route add &lt;dst&gt; &lt;mask&gt; &lt;gw&gt;</code>；<code>route del &lt;dst&gt; &lt;mask&gt;</code></td></tr><tr><td><a href="./commands/tcpcc_test.html">tcpcc_test</a></td><td>TCP 拥塞控制测试</td><td>无参数</td></tr><tr><td><a href="./commands/tcpstats.html">tcpstats</a></td><td>每连接 TCP 统计</td><td>无参数（cwnd/ssthresh/rto/sack/...）</td></tr><tr><td><a href="./commands/tcptest.html">tcptest</a></td><td>TCP 环回测试</td><td>无参数</td></tr><tr><td><a href="./commands/wget.html">wget</a></td><td>通过 HTTP(S) 下载</td><td>⚑ <code>wget https://...</code> → TLS（默认端口 443，否则 80）；<code>wget &lt;http://host:port/path&gt;</code> URL 形式；遗留 3 参数形式 <code>wget &lt;host&gt; [port] [path]</code></td></tr></tbody></table><h2 id="camera-10-—-摄像头-遗留端口-历史标签名" tabindex="-1">camera (10) — 摄像头 + 遗留端口（历史标签名） <a class="header-anchor" href="#camera-10-—-摄像头-遗留端口-历史标签名" aria-label="Permalink to &quot;camera (10) — 摄像头 + 遗留端口（历史标签名）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>命令</th><th>用途</th><th>隐藏 / 扩展语法</th></tr></thead><tbody><tr><td><a href="./commands/gameport.html">gameport</a></td><td>游戏端口状态</td><td>无参数</td></tr><tr><td><a href="./commands/gameporttest.html">gameporttest</a></td><td>游戏端口测试</td><td>无参数</td></tr><tr><td><a href="./commands/ir.html">ir</a></td><td>红外接收器状态</td><td>无参数</td></tr><tr><td><a href="./commands/irtest.html">irtest</a></td><td>IR 测试（NEC/RC5/RC6/SIRC）</td><td>无参数</td></tr><tr><td><a href="./commands/parallel.html">parallel</a></td><td>并行端口状态</td><td>无参数</td></tr><tr><td><a href="./commands/paralleltest.html">paralleltest</a></td><td>并行端口测试</td><td>无参数</td></tr><tr><td><a href="./commands/scsi.html">scsi</a></td><td>SCSI 设备扫描</td><td>无参数</td></tr><tr><td><a href="./commands/scsitest.html">scsitest</a></td><td>SCSI 测试</td><td>无参数</td></tr><tr><td><a href="./commands/uvc.html">uvc</a></td><td>UVC 摄像头状态</td><td>无参数</td></tr><tr><td><a href="./commands/uvctest.html">uvctest</a></td><td>UVC 摄像头测试</td><td>无参数</td></tr></tbody></table><h2 id="usb-9-—-usb-服务" tabindex="-1">usb (9) — USB 服务 <a class="header-anchor" href="#usb-9-—-usb-服务" aria-label="Permalink to &quot;usb (9) — USB 服务&quot;">​</a></h2><table tabindex="0"><thead><tr><th>命令</th><th>用途</th><th>隐藏 / 扩展语法</th></tr></thead><tbody><tr><td><a href="./commands/usb.html">usb</a></td><td>USB 主机状态</td><td>无参数</td></tr><tr><td><a href="./commands/usbdev.html">usbdev</a></td><td>USB 设备详情</td><td>无参数</td></tr><tr><td>usb_core_test / usb_hotplug_test / usb_hub_test / usb_kbd_test / usb_mouse_test / usb_serial_test / usb_storage_test (7)</td><td>USB 测试家族</td><td>无参数</td></tr></tbody></table><h2 id="power-8-—-电源服务" tabindex="-1">power (8) — 电源服务 <a class="header-anchor" href="#power-8-—-电源服务" aria-label="Permalink to &quot;power (8) — 电源服务&quot;">​</a></h2><table tabindex="0"><thead><tr><th>命令</th><th>用途</th><th>隐藏 / 扩展语法</th></tr></thead><tbody><tr><td><a href="./commands/halt.html">halt</a></td><td>停机 CPU</td><td>无参数</td></tr><tr><td><a href="./commands/poweroff.html">poweroff</a></td><td>关机（ACPI）</td><td>无参数</td></tr><tr><td><a href="./commands/shutdown.html">shutdown</a></td><td>关机（第二种拼写）</td><td>无参数</td></tr><tr><td><a href="./commands/sleep.html">sleep</a></td><td>挂起 N 秒</td><td>⚑ <code>sleep &lt;seconds&gt;</code> — 允许小数值（<code>sleep 0.5</code>）</td></tr><tr><td>halt_test / poweroff_test / reboot_test / suspend_test (4)</td><td>电源路径探针</td><td>各自执行真实路径且可能终结会话 — 电源向导会警告 + 确认</td></tr></tbody></table><h2 id="crypto-4-—-加密-ssh" tabindex="-1">crypto (4) — 加密 + ssh <a class="header-anchor" href="#crypto-4-—-加密-ssh" aria-label="Permalink to &quot;crypto (4) — 加密 + ssh&quot;">​</a></h2><table tabindex="0"><thead><tr><th>命令</th><th>用途</th><th>隐藏 / 扩展语法</th></tr></thead><tbody><tr><td><a href="./commands/cryptotest.html">cryptotest</a></td><td>加密原语测试（SHA-256、AES-128、HMAC）</td><td>无参数</td></tr><tr><td><a href="./commands/dhtest.html">dhtest</a></td><td>Diffie-Hellman 测试</td><td>无参数</td></tr><tr><td><a href="./commands/ssh.html">ssh</a></td><td>SSH 客户端</td><td>⚑ <code>ssh &lt;ip|host&gt; [port=2222] [user=oc] [password=oc]</code>；密码 <strong><code>-</code> = 公钥认证</strong>，使用 <code>/etc/ssh_client_key</code>（密钥缺失时回退到密码）</td></tr><tr><td><a href="./commands/sshd.html">sshd</a></td><td>SSH 服务器</td><td>⚑ <code>sshd [port]</code> — 默认 22；同时仅一个会话</td></tr></tbody></table><h2 id="recovery-7-—-杂项历史命令" tabindex="-1">recovery (7) — 杂项历史命令 <a class="header-anchor" href="#recovery-7-—-杂项历史命令" aria-label="Permalink to &quot;recovery (7) — 杂项历史命令&quot;">​</a></h2><table tabindex="0"><thead><tr><th>命令</th><th>用途</th><th>隐藏 / 扩展语法</th></tr></thead><tbody><tr><td><a href="./commands/crashtest.html">crashtest</a></td><td>崩溃处理测试触发器</td><td>⚑ <code>crashtest panic|exc|pf|assert|wd|ovf|dump|policy [halt|reboot]</code> — 8 种模式（见 <a href="./hidden-commands.html">hidden-commands.md</a>）</td></tr><tr><td><a href="./commands/dumpinfo.html">dumpinfo</a></td><td>核心转储状态</td><td>无参数（缓冲区大小、使用量）</td></tr><tr><td><a href="./commands/echo.html">echo</a></td><td>打印参数</td><td>支持 <code>$VAR</code> 展开（ush 的 expand_env 先行运行）</td></tr><tr><td><a href="./commands/help.html">help</a></td><td>内建 + 注册表列表</td><td>⚑ <code>help -a</code> / <code>--all</code>，<code>help -w</code> / <code>--wp</code></td></tr><tr><td>help_a_test / help_default_test / help_wp_test (3)</td><td>注册表列表不变量测试</td><td>无参数（见 <a href="./hidden-commands.html">hidden-commands.md</a>）</td></tr></tbody></table><h2 id="watchdog-5-—-klog-watchdog-health" tabindex="-1">watchdog (5) — klog + watchdog + health <a class="header-anchor" href="#watchdog-5-—-klog-watchdog-health" aria-label="Permalink to &quot;watchdog (5) — klog + watchdog + health&quot;">​</a></h2><table tabindex="0"><thead><tr><th>命令</th><th>用途</th><th>隐藏 / 扩展语法</th></tr></thead><tbody><tr><td><a href="./commands/dmesg.html">dmesg</a></td><td>内核日志</td><td>⚑ <code>dmesg [N]</code> — N 行，默认 30，上限 1024；页脚 <code>-- &lt;shown&gt; lines (ring &lt;n&gt;/1024, dropped &lt;d&gt;) --</code></td></tr><tr><td><a href="./commands/health.html">health</a></td><td>健康快照</td><td>⚑ <code>health watch</code>（实时监视直到 ENTER）/ <code>health export [path]</code></td></tr><tr><td><a href="./commands/logcat.html">logcat</a></td><td>过滤后的内核日志流</td><td>⚑ <code>logcat [-l &lt;level&gt;] [-m &lt;module&gt;] [-k &lt;keyword&gt;] [-t &lt;seconds&gt;] [-n &lt;count 1..1024&gt;] [-f]</code> — <code>-f</code> 跟随实时输出（ENTER 退出）</td></tr><tr><td><a href="./commands/logctl.html">logctl</a></td><td>内核日志级别控制</td><td>⚑ 11 个子命令：<code>status|level [-1..4]|enable|disable &lt;level&gt;|clear|flush|rotate|threshold &lt;bytes&gt;|export [path]|filter &lt;clear|[level] [module] [keyword]&gt;|test</code></td></tr><tr><td><a href="./commands/watchdog.html">watchdog</a></td><td>watchdog 控制</td><td>⚑ <code>watchdog [status|slots|hw &lt;status|start|stop|feed|timeout &lt;2..63s&gt;&gt;|start|stop|feed &lt;id&gt;|timeout &lt;id&gt; &lt;ms 100..3600000&gt;|register &lt;name&gt; &lt;ms&gt; &lt;0=panic 1=reboot 2=kill 3=log&gt;|test &lt;kill|panic|log&gt;]</code></td></tr></tbody></table><h2 id="time-4-—-时钟源" tabindex="-1">time (4) — 时钟源 <a class="header-anchor" href="#time-4-—-时钟源" aria-label="Permalink to &quot;time (4) — 时钟源&quot;">​</a></h2><table tabindex="0"><thead><tr><th>命令</th><th>用途</th><th>隐藏 / 扩展语法</th></tr></thead><tbody><tr><td><a href="./commands/hpet.html">hpet</a></td><td>HPET 定时器状态</td><td>无参数</td></tr><tr><td><a href="./commands/pmtimer.html">pmtimer</a></td><td>ACPI PM 定时器状态</td><td>无参数</td></tr><tr><td><a href="./commands/rtc.html">rtc</a></td><td>CMOS RTC 状态</td><td>无参数</td></tr><tr><td><a href="./commands/tsc.html">tsc</a></td><td>TSC 计数器状态</td><td>无参数</td></tr></tbody></table><hr><h2 id="参数如何到达其语法" tabindex="-1">参数如何到达其语法 <a class="header-anchor" href="#参数如何到达其语法" aria-label="Permalink to &quot;参数如何到达其语法&quot;">​</a></h2><p>上面大多数命令是服务 op 之上的薄封装，其参数处理方式 解释了几个令用户意外的行为：</p><ul><li>标准应用骨架（<code>l1_api_syscall.h</code>、<code>l1svc_main</code>）将 <code>argv[1..]</code> 以单空格连接成一条 <strong>256 字节参数行</strong>， 通过 <code>sys_l1svc(cat, op, arg, out, 32768)</code> 发送， 并打印结果。因此多词语法（<code>firewall add in drop tcp port 22</code>） 按输入原样工作 —— 但超过 256 字节的部分会丢失。</li><li>输出缓冲是静态 <strong>32 KiB</strong>。<code>help -a</code> 的完整注册表 列表（约 12 KiB）放得下；栈截断变体是很久前已修复的 bug。</li><li>rc 非零时封装打印 <code>&lt;app&gt;: service call failed (rc=-1)</code> — 300 个应用中约 150 个共享的这一模板（该 i18n 键总计被 250 个应用共享）。看到它时，真实情况在 <code>dmesg</code> 里：统一排查见 <a href="./../troubleshooting/error-catalog.html">../troubleshooting/error-catalog.md</a> §7.1。</li><li>少数命令不是封装：<code>files</code> 和 <code>run</code> fork+execve 真实 程序；<code>ush</code>、各编辑器以及平坦的 <code>l1</code> 探针自己做 系统调用。</li><li><code>dmesg</code> 连接其 argv 时不加空格（单一 token）—— 出于 历史兼容保留的怪癖：始终用 <code>dmesg 100</code>，绝不要 <code>dmesg -n 100</code>。</li></ul><h2 id="命令名怪癖" tabindex="-1">命令名怪癖 <a class="header-anchor" href="#命令名怪癖" aria-label="Permalink to &quot;命令名怪癖&quot;">​</a></h2><p>值得了解的已冻结历史拼写：</p><table tabindex="0"><thead><tr><th>怪癖</th><th>解释</th></tr></thead><tbody><tr><td><code>edit</code> == <code>nano</code></td><td>逐字节相同的界面；<code>edit</code> 是 v2.2.0 拼写</td></tr><tr><td><code>shutdown</code> == <code>poweroff</code></td><td>两者拼写同一个电源 op</td></tr><tr><td><code>rtl8168</code> 内部打印 <code>rtl8169: ...</code></td><td>驱动家族名；命令界面是 <code>rtl8168</code></td></tr><tr><td><code>mounts</code> == 裸 <code>mount</code></td><td>两者都是列出；只有 <code>mount &lt;type&gt; &lt;dev&gt; &lt;path&gt;</code> 执行挂载</td></tr><tr><td><code>reboot</code> 标签为 <code>ota</code>，<code>reboot_test</code> 为 <code>power</code></td><td>已冻结的类别标签，无语义</td></tr><tr><td><code>lspci</code> 标签为 <code>net</code></td><td>它共享 net 家族的 op 编号</td></tr><tr><td><code>ssh</code>/<code>sshd</code> 标签为 <code>crypto</code></td><td>加密服务拥有它们的 op</td></tr><tr><td>ACPI/I2C/PCI/MSI 工具标签为 <code>input</code></td><td>历史的&quot;芯片组/输入&quot;桶</td></tr><tr><td>SCSI/gameport/parallel/IR 标签为 <code>camera</code></td><td>遗留端口桶</td></tr><tr><td>commands/ 中是 <code>mkfs-fat32.md</code> 而提示符下是 <code>mkfs.fat32</code></td><td>文档树避免文件名中的点</td></tr><tr><td><code>help</code> 既存在为内建也存在为应用</td><td>相同的 12 行 + 注册表计数，相同 flag</td></tr></tbody></table><h2 id="mega-应用菜单清单" tabindex="-1">mega 应用菜单清单 <a class="header-anchor" href="#mega-应用菜单清单" aria-label="Permalink to &quot;mega 应用菜单清单&quot;">​</a></h2><p>作为参考，各向导共暴露 <strong>113 个单键菜单项</strong>： update 5 步、disk-tool 7+3+5+3 = 18、net-tool 9+4+4+4 = 21、 sound-tool 5+6+3 = 14、files 8、sysdiag 7+4+5 = 16、hwinfo 8+4+4+6 = 22、power 5+4 = 9 —— 外加 <strong>155 个逐字 op/程序门</strong>（30 + 16 + 5 + 17 + 10 + 46 + 26 + 9 + update 的 1）。每条破坏性向导路径 都使用&quot;重新输入设备名 + 裸 <code>y</code>&quot;双重确认；classic 与 <code>direct</code> 分发按设计跳过提示（脚本保持历史语义）。 <code>sysdiag</code> 刻意不让 <code>crashtest</code> 出现在其菜单上。</p><h2 id="_12-个-ush-内建命令" tabindex="-1">12 个 ush 内建命令 <a class="header-anchor" href="#_12-个-ush-内建命令" aria-label="Permalink to &quot;12 个 ush 内建命令&quot;">​</a></h2><table tabindex="0"><thead><tr><th>内建</th><th>用途</th><th>隐藏 / 注意</th></tr></thead><tbody><tr><td><code>cd [dir]</code></td><td>切换目录（shell 状态）</td><td>无参数 = <code>/</code></td></tr><tr><td><code>help [-a|-w]</code></td><td>帮助文本</td><td>⚑ <code>-a</code>/<code>--all</code>、<code>-w</code>/<code>--wp</code></td></tr><tr><td><code>export VAR=val</code></td><td>设置环境变量</td><td>32 个变量，名 32 / 值 128 字节</td></tr><tr><td><code>alias name=val</code></td><td>设置命令别名</td><td>裸 <code>alias</code> 列出；<code>alias name</code> 打印单个；也支持 <code>alias name value...</code></td></tr><tr><td><code>unalias name</code></td><td>删除别名</td><td>无参数调用时报 usage 错误</td></tr><tr><td><code>env</code></td><td>显示环境变量</td><td></td></tr><tr><td><code>set</code></td><td>显示一个变量</td><td><code>set VAR</code> 打印 <code>VAR=value</code></td></tr><tr><td><code>history</code></td><td>命令历史</td><td>16 条，每条 256 字节</td></tr><tr><td><code>jobs</code></td><td>列出后台作业</td><td>16 个作业槽</td></tr><tr><td><code>fg [job]</code></td><td>（被识别，拒绝执行）</td><td>打印 <code>ush: job control requires external programs</code></td></tr><tr><td><code>bg</code></td><td>（被识别，拒绝执行）</td><td>相同消息</td></tr><tr><td><code>exit</code></td><td>（被识别，拒绝执行）</td><td><code>ush: &#39;exit&#39; is not available; use &#39;shutdown&#39; to power off, &#39;reboot&#39; to restart</code></td></tr></tbody></table><p>你可能记得的其他所有&quot;内建&quot;（<code>ls</code>、<code>cat</code>、<code>ps</code>、<code>kill</code>、 <code>nano</code> ...）现在都是经 fork+execve 到达的注册表应用。</p><hr><h2 id="隐藏参数总清单" tabindex="-1">隐藏参数总清单 <a class="header-anchor" href="#隐藏参数总清单" aria-label="Permalink to &quot;隐藏参数总清单&quot;">​</a></h2><p><code>help</code> 提示从不展示的一切，集中在一处（35+ 个面）：</p><ol><li><code>help -a</code> / <code>--all</code> / <code>-w</code> / <code>--wp</code>（ush 内建与该应用皆可）</li><li><code>top -n N</code> — 刷新次数（1..10）</li><li><code>ln -s &lt;abs-target&gt; &lt;linkpath&gt;</code> — 符号链接</li><li><code>sed s/old/new/[g]</code>、<code>sed -n Np</code>、<code>sed Nd</code>、可选尾随文件</li><li><code>p2test utf8|read0|pipe</code> — 探针选择器</li><li><code>health watch</code> / <code>health export [path]</code></li><li>8 个 mega 应用的 <code>direct</code> 关键字</li><li><code>update status</code> / <code>--status</code> / <code>--local &lt;path&gt;</code> / <code>local &lt;path&gt;</code> / 裸在线流程</li><li><code>crashtest</code> 8 种模式 + <code>policy halt|reboot</code></li><li><code>watchdog</code> 完整子命令语法（status/slots/hw/start/stop/feed/timeout/register/test）</li><li><code>logctl</code> 11 个子命令</li><li><code>logcat -l -m -k -t -n -f</code></li><li><code>dmesg [N]</code></li><li><code>wifi scan|test|sdio</code></li><li><code>bt usb|uart|test</code></li><li><code>dns &lt;name&gt; [aaaa|cname|mx|txt|ns|srv]</code></li><li><code>wget https://...</code>（TLS）与 3 参数形式</li><li><code>ssh</code> 密码 <code>-</code> = 公钥；<code>sshd [port]</code></li><li><code>firewall add/del/policy/ct/reset</code> 语法</li><li><code>route add/del</code></li><li><code>ip &lt;ip&gt; &lt;mask&gt; &lt;gw&gt;</code> 设置形式</li><li><code>config list|get|set|restore|path</code></li><li><code>play [device] [rate 4000-96000]</code>、<code>volume [device] [0-100]</code></li><li><code>sleep</code> 小数秒</li><li><code>uname -a</code></li><li><code>serial_encoding [utf8|gbk]</code></li><li><code>ime -i</code></li><li><code>i2cget &lt;bus&gt; &lt;addr&gt; [reg]</code>、<code>i2cset &lt;bus&gt; &lt;addr&gt; &lt;reg&gt; &lt;val&gt;</code>（十六进制）</li><li><code>pcidump &lt;bus:dev.fn&gt;</code></li><li><code>nice &lt;tid&gt; &lt;prio 0..31&gt;</code></li><li>块设备参数：<code>fsck/abdisk/install/grub-install/disk_rw_test/partition_test/fs_mount_test &lt;device&gt;</code>；<code>mount &lt;type&gt; &lt;device&gt; &lt;path&gt;</code>；<code>umount &lt;path&gt;</code>；<code>fatmount [dev path]</code></li><li><code>ldd &lt;program&gt;</code></li><li><code>parted [device]</code> 可选参数</li><li><code>echo</code> 的 <code>$VAR</code> 展开</li><li>约 93 个测试桩（都可裸运行 — <a href="./hidden-commands.html">hidden-commands.md</a>）</li></ol><h2 id="help-不会强调的内容" tabindex="-1">help 不会强调的内容 <a class="header-anchor" href="#help-不会强调的内容" aria-label="Permalink to &quot;help 不会强调的内容&quot;">​</a></h2><ul><li><strong>上述 35 个隐藏面没有一个出现在注册表提示里。</strong><code>help -a</code> 为每个程序打印一行提示；子命令语法只能通过 带一个错误参数运行该命令（多数会打印 <code>usage:</code> 行）或 阅读 <a href="./commands/">commands/</a> 看到。</li><li><strong>测试桩</strong>（约 93 个程序）像其他命令一样列出 —— 没有任何标记表明它们是测试。它们可以安全运行，但少数 刻意制造破坏（<code>crashtest</code>、电源路径探针、 <code>stackovf</code>、<code>badapp</code>）；见 <a href="./hidden-commands.html">hidden-commands.md</a>。</li><li><code>help -w</code> 中的类别标签是历史产物，非语义（见上文 怪癖说明）。</li><li><code>fg</code>/<code>bg</code> 出现在内建表中但<strong>未实现</strong> （它们打印拒绝消息）；<code>jobs</code> 与 <code>cmd &amp;</code> 是真实的。</li><li>提示文本本身是双语的（每个应用的 <code>i18n/{en,zh}.json</code> 中的 <code>_hint</code> 键，构建时消费）； 缺失翻译是构建违规，因此你永远不会看到原始键作为提示。</li></ul><h2 id="运行时发现语法" tabindex="-1">运行时发现语法 <a class="header-anchor" href="#运行时发现语法" aria-label="Permalink to &quot;运行时发现语法&quot;">​</a></h2><p>当你无法查阅本手册时：</p><ol><li>带一个故意错误的参数输入该命令 — 多数语法会 打印其 <code>usage:</code> 行（<code>crashtest x</code>、<code>watchdog x</code>、<code>logctl x</code>、 <code>firewall x</code>、<code>config x</code>）。</li><li>先 <code>help -w</code> 找到家族，再用该家族的状态命令 （裸调用几乎总是状态形式）。</li><li>向导兼任语法教师：它们提出的问题与位置参数语法 一一对应（net-tool 的静态 IP 路径按 <code>ip &lt;a&gt; &lt;m&gt; &lt;g&gt;</code> 的确切顺序询问地址 → 掩码 → 网关）。</li></ol><h2 id="相关页面" tabindex="-1">相关页面 <a class="header-anchor" href="#相关页面" aria-label="Permalink to &quot;相关页面&quot;">​</a></h2><ul><li><a href="./ush-reference.html">ush-reference.md</a> — shell、行编辑器、管道、 重定向、编辑器与 TUI 按键表</li><li><a href="./hidden-commands.html">hidden-commands.md</a> — 约 93 个测试桩、 3 个 help 门、msitest 的真实 MSI 注入</li><li><a href="./mega-apps.html">mega-apps.md</a> — 8 个向导应用的菜单</li><li><a href="./../troubleshooting/error-catalog.html">../troubleshooting/error-catalog.md</a> — 这些命令中任何一个失败时该怎么办</li></ul>`,80)])])}const f=d(r,[["render",c]]);export{p as __pageData,f as default};
